// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrancy_bonus} from "../src/Reentrancy_bonus.sol";

contract InvMutTest is Test {
    Reentrancy_bonus c;
    function setUp() public { c = new Reentrancy_bonus(); }

    function testFuzz_property(address recipient, uint256 funding) public {
        // Only plain EOAs (no code) can safely receive the ETH payout via low-level call,
        // so the whole sequence is admissible and succeeds in both versions.
        vm.assume(recipient.code.length == 0);
        vm.assume(uint256(uint160(recipient)) != uint256(uint160(address(c))));
        funding = bound(funding, 1 ether, 1000 ether);

        vm.deal(address(c), funding);
        uint256 before = address(c).balance;

        // First bonus withdrawal pays exactly 100 wei once.
        c.getFirstWithdrawalBonus(recipient);
        // A direct repeat of the same withdrawal must pay nothing more.
        c.withdrawReward(recipient);

        assertEq(address(c).balance, before - 100,
            "repeated withdrawal to same recipient must not pay out twice");
    }
}
